// ---------------------------------------------------------------------------
// Compile-time structural check

/** T with every string-literal union widened to string, number literals to number, tuples to arrays. */
export type Widen<T> = T extends string
  ? string
  : T extends number
    ? number
    : T extends boolean
      ? boolean
      : T extends null | undefined
        ? T
        : T extends readonly (infer U)[]
          ? Widen<U>[]
          : T extends object
            ? { [K in keyof T]: Widen<T[K]> }
            : T;

/** Checks `value` against Widen<T> at compile time, then narrows it to T. */
function typed<T>(value: Widen<T>): T {
  return value as unknown as T;
}

