// ---------------------------------------------------------------------------
// Lookup through index.json

/**
 * Fixture for an endpoint, resolved through index.json, or null if none exists.
 * `path` is the concrete path ("/programs/northgate/ledger"); a query string is
 * ignored. With `afterFund`, the `after_fund` file is preferred and the routed
 * file is the fallback. Returns a deep copy, so callers may mutate it.
 */
export function getFixture<M extends string, P extends string>(
  method: M,
  path: P,
  opts?: { afterFund?: boolean },
): ResponseFor<Uppercase<M>, P> | null {
  const key = `${method.toUpperCase()} ${path.split("?")[0]}`;
  const { endpoints, after_fund } = fixtures.index;
  const file = (opts?.afterFund ? after_fund[key] : undefined) ?? endpoints[key];
  if (!file) return null;
  const data = fixtureFiles[file];
  if (data === undefined) return null;
  return structuredClone(data) as ResponseFor<Uppercase<M>, P>;
}

// ---------------------------------------------------------------------------
// Runtime contract check

type Allowed = readonly (string | number)[];

/** Keys whose values (or array items, or object keys for *_unlock / failing_filters) come from one closed set. */
const KEY_ENUMS: Record<string, Allowed> = {
  process_tags: PROCESS_TAGS,
  processes: PROCESS_TAGS,
  material: MATERIALS,
  materials: MATERIALS,
  tolerance_class: TOLERANCE_CLASSES,
  required_certs: CERT_TYPES,
  cert_unlock: CERT_TYPES,
  capacity_unlock: PROCESS_TAGS,
  failing_filters: FILTER_CODES,
  reason_code: FILTER_CODES,
  categories: TRAINING_CATEGORIES,
  recipient_type: RECIPIENT_TYPES,
  source: SHOP_SOURCES,
  shop_source: SHOP_SOURCES,
  tag_source: TAG_SOURCES,
  solver: SOLVERS,
  origin: TXN_ORIGINS,
  state: PROGRAM_STATES,
  kind: GAP_KINDS,
  multiplier: MULTIPLIERS,
};

function checkValue(allowed: Allowed, value: unknown, where: string, out: string[]): void {
  if (value === null) return;
  const items = Array.isArray(value)
    ? value
    : typeof value === "object"
      ? Object.keys(value as object)
      : [value];
  for (const v of items) {
    if (!allowed.includes(v as string | number)) out.push(`${where}: ${JSON.stringify(v)}`);
  }
}

function walk(node: unknown, where: string, out: string[]): void {
  if (Array.isArray(node)) {
    node.forEach((v, i) => walk(v, `${where}[${i}]`, out));
    return;
  }
  if (node === null || typeof node !== "object") return;
  for (const [k, v] of Object.entries(node)) {
    const allowed = KEY_ENUMS[k];
    if (allowed) checkValue(allowed, v, `${where}.${k}`, out);
    walk(v, `${where}.${k}`, out);
  }
}

/** Contract problems in the fixtures (empty when all is well). */
export function checkFixtures(): string[] {
  const out: string[] = [];
  const f = fixtures;
  const one = (allowed: Allowed, v: unknown, where: string) => checkValue(allowed, v, where, out);

  for (const [file, data] of Object.entries(fixtureFiles)) {
    if (file !== "index.json") walk(data, file, out);
  }
  const indexed = [...Object.values(f.index.endpoints), ...Object.values(f.index.after_fund)];
  for (const file of indexed) {
    if (!(file in fixtureFiles)) out.push(`index.json names ${file}, which fixtures.ts does not import`);
  }

  // Ambiguous keys (status, category, type, label), checked per object kind.
  one(["ok"], f.health.status, "health.json.status");
  for (const j of f.partsUpload.jobs) one(JOB_STATUSES, j.status, `parts_upload.json ${j.id}.status`);
  for (const j of f.jobs.jobs) one(JOB_STATUSES, j.status, `jobs.json ${j.id}.status`);
  for (const j of f.jobsAfterFund.jobs) one(JOB_STATUSES, j.status, `jobs_after_fund.json ${j.id}.status`);
  const assignments = [
    ...f.route.assignments,
    ...f.assignments.assignments,
    ...f.assignmentsAfterFund.assignments,
    ...f.fundTP01.unblocked_jobs,
    ...f.fundTP02.unblocked_jobs,
  ];
  for (const a of assignments) {
    one(ASSIGNMENT_STATUSES, a.status, `assignment ${a.job_id}.status`);
    one(["regular", "sme_direct"], a.category, `assignment ${a.job_id}.category`);
  }
  const txns = [
    ...f.ledger.transactions,
    ...f.ledgerAfterFund.transactions,
    f.fundTP01.training_txn,
    f.fundTP02.training_txn,
  ];
  for (const t of txns) {
    one(TXN_TYPES, t.type, `txn ${t.id}.type`);
    one(CREDIT_CATEGORIES, t.category, `txn ${t.id}.category`);
  }
  for (const ledger of [f.ledger, f.ledgerAfterFund]) {
    for (const row of ledger.multiplier_breakdown) one(CREDIT_CATEGORIES, row.category, "multiplier_breakdown.category");
  }
  const packages = [
    ...f.gaps.suggestions,
    ...f.gapsAfterFund.suggestions,
    f.fundTP01.package,
    f.fundTP02.package,
  ];
  for (const p of packages) {
    one(TRAINING_CATEGORIES, p.category, `package ${p.id}.category`);
    one(PACKAGE_STATUSES, p.status, `package ${p.id}.status`);
  }
  for (const s of f.shops.shops) {
    one(SHOP_LABELS, s.label, `shops.json ${s.id}.label`);
    for (const c of s.cert_summary) {
      one(CERT_TYPES, c.type, `shops.json ${s.id}.cert_summary.type`);
      one(CERT_STATUSES, c.status, `shops.json ${s.id}.cert_summary.status`);
    }
  }
  for (const detail of [f.shopDemo, f.shopDemoAfterFund]) {
    one(SHOP_LABELS, detail.shop.label, `shop ${detail.shop.id}.label`);
    for (const c of detail.certifications) {
      one(CERT_TYPES, c.type, `shop ${detail.shop.id} certification.type`);
      one(CERT_STATUSES, c.status, `shop ${detail.shop.id} certification.status`);
    }
    for (const o of detail.offers) one(ASSIGNMENT_STATUSES, o.status, `shop ${detail.shop.id} offer ${o.job_id}.status`);
    for (const t of detail.training) {
      one(PACKAGE_STATUSES, t.status, `shop ${detail.shop.id} training ${t.package_id}.status`);
      one(TRAINING_CATEGORIES, t.category, `shop ${detail.shop.id} training ${t.package_id}.category`);
    }
  }
  return out;
}
